const REPEAT_TAGS = ["repeat", "repeat-x", "repeat-y", "no-repeat"] as const;
const REPEAT_INDEX = new Map<string, number>(REPEAT_TAGS.map((s, i): [string, number] => [s, i]));

export function writeRepeat(w: Writer, v: Repeat, t: Tables): void {
  void t;
  w.u32(tagIndex("Repeat", REPEAT_INDEX, v));
}

export function readRepeat(r: Reader, t: Tables): Repeat {
  void t;
  return REPEAT_TAGS[r.tag("Repeat", REPEAT_TAGS.length)]!;
}

export type PatternSrc =
  | { kind: "bitmap"; v: number }
  | { kind: "image"; v: ImageSrc };


export function writePatternSrc(w: Writer, v: PatternSrc, t: Tables): void {
  void t;
  switch (v.kind) {
    case "bitmap":
      w.u32(0);
      w.u32(v.v);
      break;

    case "image":
      w.u32(1);
      writeImageSrc(w, v.v, t);
      break;

    default:
      throw new EncodeError(`"${String((v as { kind: string }).kind)}" is not a variant of PatternSrc`);

  }
}

export function readPatternSrc(r: Reader, t: Tables): PatternSrc {
  void t;
  const tag = r.u32();
  let out: PatternSrc;
  switch (tag) {
    case 0:
      out = { kind: "bitmap", v: r.ref(4, "bitmaps") };
      break;

    case 1:
      out = { kind: "image", v: readImageSrc(r, t) };
      break;

    default:
      throw new DecodeError("BadTag", `${tag} is not a variant of PatternSrc`);

  }
  return out;
}

/**
 * `ctx.createPattern`: `transform` is applied with `pat.setTransform` when the canvas supports it, else ignored
 * (the TS test). With `tile` the pattern is the TS `tilePattern` (`@universal-office/charts`, `image.ts`): the
 * painter reads the live transform (`hypot(a, b)`, `hypot(c, d)`) and the decoded image size, so the list
 * carries only the parameters; `repeat` is `repeat` and `transform` is ignored.
 */
export interface PatternRes {
  src: PatternSrc;
  repeat: Repeat;
  transform?: Mat6;
  tile?: TileDef;
}

export function writePatternRes(w: Writer, v: PatternRes, t: Tables): void {
  void t;
  w.bitmap([v.transform !== undefined, v.tile !== undefined]);
  writePatternSrc(w, v.src, t);
  writeRepeat(w, v.repeat, t);
  if (v.transform !== undefined) {
    writeMat6(w, v.transform, t);
  }
  if (v.tile !== undefined) {
    writeTileDef(w, v.tile, t);
  }
}

export function readPatternRes(r: Reader, t: Tables): PatternRes {
  void t;
  const bm = r.bitmap(2);
  const f_src = readPatternSrc(r, t);
  const f_repeat = readRepeat(r, t);
  let f_transform: Mat6 | undefined;
  if (bitAt(bm, 0)) f_transform = readMat6(r, t);
  let f_tile: TileDef | undefined;
  if (bitAt(bm, 1)) f_tile = readTileDef(r, t);
  const o: PatternRes = { src: f_src, repeat: f_repeat };
  if (f_transform !== undefined) o.transform = f_transform;
  if (f_tile !== undefined) o.tile = f_tile;
  return o;
}

/**
 * The model-side parameters of an `<a:tile>` use (`imageTile`, render.ts:522-530): the natural size of the tile
 * is `image px x unit x scale` (`unit` = 914400 / dpi, or 9525 without a resolution), `tx`/`ty` are EMU (the
 * painter multiplies them by `scale`).
 */
export interface TileParams {
  unitX: number;
  unitY: number;
  sx: number;
  sy: number;
  tx: number;
  ty: number;
  /** `a:tile algn` */
  algn?: string;
  /** `x`, `y` or `xy` */
  flip?: string;
}

export function writeTileParams(w: Writer, v: TileParams, t: Tables): void {
  void t;
  w.bitmap([v.algn !== undefined, v.flip !== undefined]);
  w.f64(v.unitX);
  w.f64(v.unitY);
  w.f64(v.sx);
  w.f64(v.sy);
  w.f64(v.tx);
  w.f64(v.ty);
  if (v.algn !== undefined) {
    w.u32(t.sym.intern(v.algn));
  }
  if (v.flip !== undefined) {
    w.u32(t.sym.intern(v.flip));
  }
}

export function readTileParams(r: Reader, t: Tables): TileParams {
  void t;
  const bm = r.bitmap(2);
  const f_unit_x = r.f64();
  const f_unit_y = r.f64();
  const f_sx = r.f64();
  const f_sy = r.f64();
  const f_tx = r.f64();
  const f_ty = r.f64();
  let f_algn: string | undefined;
  if (bitAt(bm, 0)) f_algn = t.sym.list[r.ref(0, "sym")]!;
  let f_flip: string | undefined;
  if (bitAt(bm, 1)) f_flip = t.sym.list[r.ref(0, "sym")]!;
  const o: TileParams = { unitX: f_unit_x, unitY: f_unit_y, sx: f_sx, sy: f_sy, tx: f_tx, ty: f_ty };
  if (f_algn !== undefined) o.algn = f_algn;
  if (f_flip !== undefined) o.flip = f_flip;
  return o;
}

/**
 * `tilePattern(ctx, img, iw, ih, natW, natH, spec, box)` of one pattern: `scale` is px per EMU, `bx` the box.
 * 
 * `nat` (the chart engine, CT-1): the natural tile size in px the producer computed with the TS arithmetic
 * (`(wPt ?? w * 0.75) * S`, render.ts:261); when present `scale` is 1, `unit_x`/`unit_y` are not read and `tx`/`ty`
 * are already px, so the painter passes the numbers to `tilePattern` as they are.
 */
export interface TileDef {
  params: TileParams;
  scale: number;
  bx: Rect4;
  nat?: Pair;
}

export function writeTileDef(w: Writer, v: TileDef, t: Tables): void {
  void t;
  w.bitmap([v.nat !== undefined]);
  writeTileParams(w, v.params, t);
  w.f64(v.scale);
  writeRect4(w, v.bx, t);
  if (v.nat !== undefined) {
    writePair(w, v.nat, t);
  }
}

export function readTileDef(r: Reader, t: Tables): TileDef {
  void t;
  const bm = r.bitmap(1);
  const f_params = readTileParams(r, t);
  const f_scale = r.f64();
  const f_bx = readRect4(r, t);
  let f_nat: Pair | undefined;
  if (bitAt(bm, 0)) f_nat = readPair(r, t);
  const o: TileDef = { params: f_params, scale: f_scale, bx: f_bx };
  if (f_nat !== undefined) o.nat = f_nat;
  return o;
}

