export type WarpPaintKind = "linear" | "radial" | "path" | "image";
const WARP_PAINT_KIND_TAGS = ["linear", "radial", "path", "image"] as const;
const WARP_PAINT_KIND_INDEX = new Map<string, number>(WARP_PAINT_KIND_TAGS.map((s, i): [string, number] => [s, i]));

export function writeWarpPaintKind(w: Writer, v: WarpPaintKind, t: Tables): void {
  void t;
  w.u32(tagIndex("WarpPaintKind", WARP_PAINT_KIND_INDEX, v));
}

export function readWarpPaintKind(r: Reader, t: Tables): WarpPaintKind {
  void t;
  return WARP_PAINT_KIND_TAGS[r.tag("WarpPaintKind", WARP_PAINT_KIND_TAGS.length)]!;
}

/**
 * The letter fill built on the raster box at warp time (`letterFill`), so it travels as a spec. `stops` are the
 * final stops `makeLinearGradient` adds (the PowerPoint sub-stops already expanded); a path gradient (`kind` path:
 * `path` is `circle`, `rect` or `shape`) is rasterized by the painter from `raw` (the model stops: position,
 * `#RRGGBB`, alpha) and `fill_to`, and falls back to the circular radial gradient of `stops` when it cannot.
 */
export interface WarpPaint {
  kind: WarpPaintKind;
  angle?: number;
  scaled?: boolean;
  stops: Stop[];
  path?: string;
  fillTo?: Edges;
  raw: RawStop[];
  image?: ImageSrc;
  /** `fillTile`: the tile parameters (scale and box come from the warp raster) */
  tile?: TileParams;
  /** `a:fillRect` of a stretched picture */
  fillRect?: Edges;
}

export function writeWarpPaint(w: Writer, v: WarpPaint, t: Tables): void {
  void t;
  w.bitmap([v.angle !== undefined, !!v.scaled, v.path !== undefined, v.fillTo !== undefined, v.image !== undefined, v.tile !== undefined, v.fillRect !== undefined]);
  writeWarpPaintKind(w, v.kind, t);
  if (v.angle !== undefined) {
    w.f64(v.angle);
  }
  w.len(v.stops.length);
  for (const e0 of v.stops) {
    writeStop(w, e0, t);
  }
  if (v.path !== undefined) {
    w.u32(t.sym.intern(v.path));
  }
  if (v.fillTo !== undefined) {
    writeEdges(w, v.fillTo, t);
  }
  w.len(v.raw.length);
  for (const e0 of v.raw) {
    writeRawStop(w, e0, t);
  }
  if (v.image !== undefined) {
    writeImageSrc(w, v.image, t);
  }
  if (v.tile !== undefined) {
    writeTileParams(w, v.tile, t);
  }
  if (v.fillRect !== undefined) {
    writeEdges(w, v.fillRect, t);
  }
}

export function readWarpPaint(r: Reader, t: Tables): WarpPaint {
  void t;
  const bm = r.bitmap(7);
  const f_kind = readWarpPaintKind(r, t);
  let f_angle: number | undefined;
  if (bitAt(bm, 0)) f_angle = r.f64();
  const f_scaled = bitAt(bm, 1);
  const f_stops = r.list(72, () => readStop(r, t));
  let f_path: string | undefined;
  if (bitAt(bm, 2)) f_path = t.sym.list[r.ref(0, "sym")]!;
  let f_fill_to: Edges | undefined;
  if (bitAt(bm, 3)) f_fill_to = readEdges(r, t);
  const f_raw = r.list(136, () => readRawStop(r, t));
  let f_image: ImageSrc | undefined;
  if (bitAt(bm, 4)) f_image = readImageSrc(r, t);
  let f_tile: TileParams | undefined;
  if (bitAt(bm, 5)) f_tile = readTileParams(r, t);
  let f_fill_rect: Edges | undefined;
  if (bitAt(bm, 6)) f_fill_rect = readEdges(r, t);
  const o: WarpPaint = { kind: f_kind, scaled: f_scaled, stops: f_stops, raw: f_raw };
  if (f_angle !== undefined) o.angle = f_angle;
  if (f_path !== undefined) o.path = f_path;
  if (f_fill_to !== undefined) o.fillTo = f_fill_to;
  if (f_image !== undefined) o.image = f_image;
  if (f_tile !== undefined) o.tile = f_tile;
  if (f_fill_rect !== undefined) o.fillRect = f_fill_rect;
  return o;
}

/**
 */
export interface RawStop {
  pos: number;
  color: string;
  alpha: number;
}

export function writeRawStop(w: Writer, v: RawStop, t: Tables): void {
  void t;
  w.f64(v.pos);
  w.u32(t.sym.intern(v.color));
  w.f64(v.alpha);
}

export function readRawStop(r: Reader, t: Tables): RawStop {
  void t;
  const f_pos = r.f64();
  const f_color = t.sym.list[r.ref(0, "sym")]!;
  const f_alpha = r.f64();
  const o: RawStop = { pos: f_pos, color: f_color, alpha: f_alpha };
  return o;
}

/**
 */
export interface WarpRun {
  text: string;
  font: WarpFont;
  x: number;
  color: string;
  stroke?: WarpStroke;
  pattern?: WarpPattern;
  spc?: number;
  paint?: WarpPaint;
  alpha?: number;
}

export function writeWarpRun(w: Writer, v: WarpRun, t: Tables): void {
  void t;
  w.bitmap([v.stroke !== undefined, v.pattern !== undefined, v.spc !== undefined, v.paint !== undefined, v.alpha !== undefined]);
  w.utf16(v.text);
  writeWarpFont(w, v.font, t);
  w.f64(v.x);
  w.u32(t.sym.intern(v.color));
  if (v.stroke !== undefined) {
    writeWarpStroke(w, v.stroke, t);
  }
  if (v.pattern !== undefined) {
    writeWarpPattern(w, v.pattern, t);
  }
  if (v.spc !== undefined) {
    w.f64(v.spc);
  }
  if (v.paint !== undefined) {
    writeWarpPaint(w, v.paint, t);
  }
  if (v.alpha !== undefined) {
    w.f64(v.alpha);
  }
}

export function readWarpRun(r: Reader, t: Tables): WarpRun {
  void t;
  const bm = r.bitmap(5);
  const f_text = r.utf16();
  const f_font = readWarpFont(r, t);
  const f_x = r.f64();
  const f_color = t.sym.list[r.ref(0, "sym")]!;
  let f_stroke: WarpStroke | undefined;
  if (bitAt(bm, 0)) f_stroke = readWarpStroke(r, t);
  let f_pattern: WarpPattern | undefined;
  if (bitAt(bm, 1)) f_pattern = readWarpPattern(r, t);
  let f_spc: number | undefined;
  if (bitAt(bm, 2)) f_spc = r.f64();
  let f_paint: WarpPaint | undefined;
  if (bitAt(bm, 3)) f_paint = readWarpPaint(r, t);
  let f_alpha: number | undefined;
  if (bitAt(bm, 4)) f_alpha = r.f64();
  const o: WarpRun = { text: f_text, font: f_font, x: f_x, color: f_color };
  if (f_stroke !== undefined) o.stroke = f_stroke;
  if (f_pattern !== undefined) o.pattern = f_pattern;
  if (f_spc !== undefined) o.spc = f_spc;
  if (f_paint !== undefined) o.paint = f_paint;
  if (f_alpha !== undefined) o.alpha = f_alpha;
  return o;
}

/**
 * The raster-op path of metafile.ts (312-330, `getImageData`).
 */
export interface MetafileRopEffect {
  rop: number;
  rect: Rect4;
  operand: number;
}

export function writeMetafileRopEffect(w: Writer, v: MetafileRopEffect, t: Tables): void {
  void t;
  w.u32(v.rop);
  writeRect4(w, v.rect, t);
  w.u32(v.operand);
}

export function readMetafileRopEffect(r: Reader, t: Tables): MetafileRopEffect {
  void t;
  const f_rop = r.u32();
  const f_rect = readRect4(r, t);
  const f_operand = r.ref(4, "bitmaps");
  const o: MetafileRopEffect = { rop: f_rop, rect: f_rect, operand: f_operand };
  return o;
}

export type SlotKind = "shape" | "background" | "paragraph" | "unit" | "chartPart" | "media" | "unitGate" | "boundsPass";
const SLOT_KIND_TAGS = ["shape", "background", "paragraph", "unit", "chartPart", "media", "unitGate", "boundsPass"] as const;
const SLOT_KIND_INDEX = new Map<string, number>(SLOT_KIND_TAGS.map((s, i): [string, number] => [s, i]));

export function writeSlotKind(w: Writer, v: SlotKind, t: Tables): void {
  void t;
  w.u32(tagIndex("SlotKind", SLOT_KIND_INDEX, v));
}

export function readSlotKind(r: Reader, t: Tables): SlotKind {
  void t;
  return SLOT_KIND_TAGS[r.tag("SlotKind", SLOT_KIND_TAGS.length)]!;
}

/**
 * The template of one slot: what `AnimBase` and `applyPart` need from the producer (px geometry, normalized by
 * the slide's px size). Per (scale, origin) list; a resize re-emits it.
 */
export interface SlotDef {
  kind: SlotKind;
  /** the shape's index in the slide (the key the playback state uses) */
  shape: number;
  /** paragraph / unit / chart part number; 0 otherwise */
  index: number;
  /** `boxBase(...)`: centre and size as a fraction of the slide */
  base: Rect4;
  /** the part's box in px (`x, y, w, h` of `applyPart`) */
  bx: Rect4;
  /** the shape's own rotation in radians (`baseRotRad`) */
  baseRotRad: number;
  /** a unit slot also has a word effect (`words`) */
  words?: boolean;
}

export function writeSlotDef(w: Writer, v: SlotDef, t: Tables): void {
  void t;
  w.bitmap([!!v.words]);
  writeSlotKind(w, v.kind, t);
  w.u32(v.shape);
  w.u32(v.index);
  writeRect4(w, v.base, t);
  writeRect4(w, v.bx, t);
  w.f64(v.baseRotRad);
}

export function readSlotDef(r: Reader, t: Tables): SlotDef {
  void t;
  const bm = r.bitmap(1);
  const f_kind = readSlotKind(r, t);
  const f_shape = r.u32();
  const f_index = r.u32();
  const f_base = readRect4(r, t);
  const f_bx = readRect4(r, t);
  const f_base_rot_rad = r.f64();
  const f_words = bitAt(bm, 0);
  const o: SlotDef = { kind: f_kind, shape: f_shape, index: f_index, base: f_base, bx: f_bx, baseRotRad: f_base_rot_rad, words: f_words };
  return o;
}

/** What a decoder has received so far in one generation, and what an encoder keeps: the entries of every table (ids are positions). */
export interface Tables {
  generation: number | undefined;
  sym: SymTable;
  faces: FaceKey[];
  media: Media[];
  derived: Derived[];
  bitmaps: Bitmap[];
}

export function newTables(): Tables {
  return { generation: undefined, sym: new SymTable(), faces: [], media: [], derived: [], bitmaps: [] };
}

/** The number of entries of every table, in declaration order. */
export function tableLens(t: Tables): number[] {
  return [t.sym.length, t.faces.length, t.media.length, t.derived.length, t.bitmaps.length];
}

/** The encoder's state: the tables (symbols are interned into them), how much of each was already sent, and the generation. */
export interface EncodeState {
  generation: number;
  tables: Tables;
  /** Per table, the entries before this index were sent by earlier messages. */
  sent: number[];
}

export function newEncodeState(generation: number, tables: Tables = newTables()): EncodeState {
  return { generation, tables, sent: new Array<number>(5).fill(0) };
}

/** Reads a `SlidesList` message. `tables` is the state of this stream of messages: the new entries are appended, a new generation replaces them, and an error leaves them as they were. */
export function decodeSlidesList(buf: Uint8Array, tables: Tables, limits: Limits = DEFAULT_LIMITS): SlidesList {
  const r = new Reader(buf, limits);
  const head = r.header(MAGIC, SCHEMA_HASH);
  if (head.message !== MSG_SLIDES_LIST) throw new DecodeError("WrongMessage", `message id ${head.message}, expected ${MSG_SLIDES_LIST}`);
  const reset = tables.generation !== head.generation;
  const saved = reset ? { generation: tables.generation, sym: tables.sym, faces: tables.faces, media: tables.media, derived: tables.derived, bitmaps: tables.bitmaps } : undefined;
  if (reset) Object.assign(tables, newTables());
  const lens = tableLens(tables);
  try {
    const n_sym = r.tableHeader(0, "sym", tables.sym.length, 8);
    const n_faces = r.tableHeader(1, "faces", tables.faces.length, 16);
    const n_media = r.tableHeader(2, "media", tables.media.length, 32);
    const n_derived = r.tableHeader(3, "derived", tables.derived.length, 16);
    const n_bitmaps = r.tableHeader(4, "bitmaps", tables.bitmaps.length, 24);
    for (let i = 0; i < n_sym; i++) tables.sym.push(r.utf16());
    for (let i = 0; i < n_faces; i++) tables.faces.push(readFaceKey(r, tables));
    for (let i = 0; i < n_media; i++) tables.media.push(readMedia(r, tables));
    for (let i = 0; i < n_derived; i++) tables.derived.push(readDerived(r, tables));
    for (let i = 0; i < n_bitmaps; i++) tables.bitmaps.push(readBitmap(r, tables));
    const msg = readSlidesList(r, tables);
    r.end();
    tables.generation = head.generation;
    return msg;
  } catch (e) {
    if (saved) {
      Object.assign(tables, saved);
    } else {
      tables.sym.truncate(lens[0]!);
      tables.faces.length = lens[1]!;
      tables.media.length = lens[2]!;
      tables.derived.length = lens[3]!;
      tables.bitmaps.length = lens[4]!;
    }
    throw e;
  }
}

/** Writes a `SlidesList` message: the header, the new entries of every table (those past `state.sent`), the body. Symbols are interned into `state.tables`. */
export function encodeSlidesList(msg: SlidesList, state: EncodeState): Uint8Array {
  const t = state.tables;
  const entries = new Writer();
  for (let i = state.sent[1]!; i < t.faces.length; i++) writeFaceKey(entries, t.faces[i]!, t);
  for (let i = state.sent[2]!; i < t.media.length; i++) writeMedia(entries, t.media[i]!, t);
  for (let i = state.sent[3]!; i < t.derived.length; i++) writeDerived(entries, t.derived[i]!, t);
  for (let i = state.sent[4]!; i < t.bitmaps.length; i++) writeBitmap(entries, t.bitmaps[i]!, t);
  const body = new Writer();
  writeSlidesList(body, msg, t);
  const w = new Writer();
  w.header(MAGIC, SCHEMA_HASH, MSG_SLIDES_LIST, state.generation);
  w.u32(state.sent[0]!);
  w.len(t.sym.length - state.sent[0]!);
  w.u32(state.sent[1]!);
  w.len(t.faces.length - state.sent[1]!);
  w.u32(state.sent[2]!);
  w.len(t.media.length - state.sent[2]!);
  w.u32(state.sent[3]!);
  w.len(t.derived.length - state.sent[3]!);
  w.u32(state.sent[4]!);
  w.len(t.bitmaps.length - state.sent[4]!);
  for (let i = state.sent[0]!; i < t.sym.length; i++) w.utf16(t.sym.list[i]!);
  w.raw(entries);
  w.raw(body);
  state.sent = tableLens(t);
  return w.finish();
}
